@Test
public void checkUnion3() {
    //Union is direct, empty and with larger K than valid input
    int k1 = 128;
    int n1 = 2 * k1;
    int k2 = 256;
    int n2 = 2000;
    DoublesSketch sketchIn1 = buildQS(k1, n1);
    //just for size
    int bytes = DoublesSketch.getUpdatableStorageBytes(k2, n2);
    Memory mem = new NativeMemory(new byte[bytes]);
    //virgin 256
    DoublesUnion union = DoublesUnion.builder().initMemory(mem).setMaxK(k2).build();
    union.update(sketchIn1);
    assertEquals(union.getMaxK(), k2);
    assertEquals(union.getEffectiveK(), k1);
    DoublesSketch result = union.getResult();
    assertEquals(result.getMaxValue(), n1 - 1, 0.0);
    assertEquals(result.getMinValue(), 0.0, 0.0);
    assertEquals(result.getK(), k1);
}

