    int bytes = DoublesSketch.getUpdatableStorageBytes(k2, n);
    Memory mem = new NativeMemory(new byte[bytes]);
    for (int i = 0; i < n; i++) {
        sketch1.update(i);
        sketch2.update(i);
        downSketch = sketch1.downSample(sketch1, k2, mem);
        assertTrue(sameStructurePredicate(sketch2, downSketch));
    }
}

