    }
}

@Test
public void checkRelativeError() {
    // Generate some random values and ensure the relative error of the decoded result is
    // within epsilon (eps) of the target.
    // This condition should always hold regardless of the random seed used.
    final double eps = 1.0 / ReservoirSize.BINS_PER_OCTAVE;
    // based on MAX_ABS_VALUE
    final int maxValue = 2146959359;
    final int numIters = 100;
    for (int i = 0; i < numIters; ++i) {
        int input = SamplingUtil.rand.nextInt(maxValue) + 1;
        int result = ReservoirSize.decodeValue(ReservoirSize.computeSize(input));
        // result must be no smaller than input
        assertTrue(result >= input, "encoded/decoded result < input: " + result + " vs " + input + " (iter " + i + ")");
        // cap on max error
        double relativeError = ((double) result - input) / input;
        assertTrue(relativeError <= eps, "Error exceeds tolerance. Expected relative error <= " + eps + "; " + "found " + relativeError);
    }
}

@Test
public void checkReadOnlyMemory() {
    final int k = 32768;
    final short encK = ReservoirSize.computeSize(k);
    final ArrayOfLongsSerDe serDe = new ArrayOfLongsSerDe();
    final ReservoirItemsSketch<Long> ris = ReservoirItemsSketch.getInstance(k);
    // get a new byte[], manually revert to v1, then reconstruct
    final byte[] sketchBytes = ris.toByteArray(serDe);
    final Memory sketchMem = new NativeMemory(sketchBytes);
    revertToV1(sketchMem, encK);
    final Memory readOnlyMem = sketchMem.asReadOnlyMemory();
    // read-only input should generate a new Memory
    Memory convertedSketch = VersionConverter.convertSketch1to2(readOnlyMem);
    assertNotEquals(readOnlyMem, convertedSketch);
    // same process on writable Memory should be in-place
    convertedSketch = VersionConverter.convertSketch1to2(sketchMem);
    assertEquals(sketchMem, convertedSketch);
}

