    assertTrue(est > k);
    println("Est: " + est);
    byte[] memArr3 = inter2.toByteArray();
    Memory srcMem2 = new NativeMemory(memArr3);
    inter3 = Sketches.wrapIntersection(srcMem2);
    resultComp2 = inter3.getResult(false, null);
    est2 = resultComp2.getEstimate();
    println("Est2: " + est2);
    inter.reset();
    inter2.reset();
    inter3.reset();
}

